-- Banque Téranga (fictive) · crédits et risques · PostgreSQL
-- À exécuter dans la base teranga_credit (créée par make demo-data). Rejouable.
DROP TABLE IF EXISTS echeances, garanties, prets, produits_credit, scores_clients CASCADE;
DROP ROLE IF EXISTS teranga_credit_app;
CREATE ROLE teranga_credit_app LOGIN PASSWORD 'Teranga#Credit2026';

CREATE TABLE produits_credit (
  id INT PRIMARY KEY, code VARCHAR(10) NOT NULL UNIQUE, libelle VARCHAR(60) NOT NULL,
  taux_min NUMERIC(5,2) NOT NULL, taux_max NUMERIC(5,2) NOT NULL, duree_max_mois INT NOT NULL
);
CREATE TABLE prets (
  id INT PRIMARY KEY, reference VARCHAR(16) NOT NULL UNIQUE, numero_client VARCHAR(12) NOT NULL,
  produit_id INT NOT NULL REFERENCES produits_credit (id), montant_accorde NUMERIC(16,2) NOT NULL,
  taux NUMERIC(5,2) NOT NULL, duree_mois INT NOT NULL, date_octroi DATE NOT NULL,
  encours NUMERIC(16,2) NOT NULL, statut VARCHAR(12) NOT NULL, agence_code CHAR(3) NOT NULL
);
CREATE INDEX ix_prets_client ON prets (numero_client);
CREATE TABLE echeances (
  id INT PRIMARY KEY, pret_id INT NOT NULL REFERENCES prets (id), numero INT NOT NULL,
  date_echeance DATE NOT NULL, montant NUMERIC(16,2) NOT NULL, payee BOOLEAN NOT NULL, date_paiement DATE
);
CREATE TABLE garanties (
  id INT PRIMARY KEY, pret_id INT NOT NULL REFERENCES prets (id), type_garantie VARCHAR(30) NOT NULL, valeur NUMERIC(16,2) NOT NULL
);
CREATE TABLE scores_clients (
  numero_client VARCHAR(12) PRIMARY KEY, score INT NOT NULL, classe_risque CHAR(1) NOT NULL, date_calcul DATE NOT NULL
);
COMMENT ON TABLE prets IS 'Portefeuille de crédits';


GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO teranga_credit_app;
